fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn pin(m:&mut BTreeMap<String,String>,p:impl AsRef<Path>){m.insert(p.as_ref().display().to_string(),hash(p));}
fn files(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();assert!(!p.is_symlink());if p.is_dir(){v.extend(files(&p))}else{v.push(p)}}v.sort();v}
fn step(name:&str,argv:Vec<String>)->Value{json!({"kind":"command","name":name,"argv":argv,"timeout_seconds":900})}
