 let mut prior:BTreeSet<String>=serde_json::from_value(read(r("prior-proof-sha256.json"))).unwrap();assert_eq!(prior.len(),23962);let(mut inventory,mut shapes,mut raw)=(vec![],BTreeMap::new(),BTreeMap::new());let(mut total_files,mut total_pairs,mut total_bytes)=(0u64,0u64,0u64);let mut vk=BTreeMap::new();
