fn archive(paths:&[PathBuf],base:&Path,out:&Path)->Value{let mut entries=BTreeMap::new();for p in paths{let bytes=fs::read(p).unwrap();let v=match String::from_utf8(bytes.clone()){Ok(s)=>json!({"sha256":hash(p),"bytes":bytes.len(),"utf8":s}),Err(_)=>json!({"sha256":hash(p),"bytes":bytes.len(),"hex":bytes.iter().map(|b|format!("{b:02x}")).collect::<String>()})};entries.insert(p.strip_prefix(base).unwrap().display().to_string(),v);}let bytes=serde_json::to_vec(&entries).unwrap();let tmp=out.with_extension("json");fs::write(&tmp,&bytes).unwrap();let f=fs::File::create(out).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(f)).status().unwrap().success());let decoded=Command::new("gzip").args(["-dc"]).arg(out).output().unwrap();assert!(decoded.status.success());assert_eq!(decoded.stdout,bytes);let back:Value=serde_json::from_slice(&decoded.stdout).unwrap();for p in paths{let entry=&back[p.strip_prefix(base).unwrap().to_str().unwrap()];let b=if let Some(s)=entry["utf8"].as_str(){s.as_bytes().to_vec()}else{let s=entry["hex"].as_str().unwrap();(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()};assert_eq!(b,fs::read(p).unwrap());}fs::remove_file(tmp).unwrap();json!({"members":paths.len(),"roundtrip_exact":true,"sha256":hash(out)})}
